type key struct{ rule, pos int }
type memo struct{ node *Node; next int; fail bool }

func (p *parser) rule(id, pos int) memo {
    k := key{id, pos}
    if m, ok := p.memo[k]; ok { return m }   // success or recorded failure
    m := p.rules[id](p, pos)                 // ordinary backtracking rule body
    m.fail = m.node == nil
    p.memo[k] = m                            // failures are cached too
    return m
}
